import subprocess, sys, math
from collections import deque

def play(seed, W=30, c=0.5):
    p = subprocess.Popen(['/app/bandit', '--seed', str(seed)], stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=1)
    obs = [deque(maxlen=W) for _ in range(10)]
    last = None
    done_line = None
    def readline():
        return p.stdout.readline().strip()
    line = readline()
    while not line.startswith('READY'):
        line = readline()
    while True:
        line = readline()
        if not line:
            break
        if line.startswith('DONE'):
            done_line = line
            break
        if line.startswith('TURN'):
            t = int(line.split()[1])
            # choose arm
            best, bestv = 0, -1e9
            total_n = sum(len(o) for o in obs)
            for i in range(10):
                n = len(obs[i])
                if n == 0:
                    v = 1e9
                else:
                    m = sum(obs[i]) / n
                    v = m + c * math.sqrt(math.log(max(total_n, 2)) / n)
                if v > bestv:
                    best, bestv = i, v
            p.stdin.write(str(best) + '\n')
            p.stdin.flush()
            r_line = readline()
            while not r_line.startswith('REWARD'):
                r_line = readline()
            r = float(r_line.split()[1])
            obs[best].append(r)
    p.wait()
    return done_line

if __name__ == '__main__':
